/-- The complier event is the event specified by the stated potential-outcome conditions. -/
def complierEvent : Set P.Ω :=
  {ω | S.DofZ false ω = false ∧ S.DofZ true ω = true}

bc13b0790c58662f.statement:
/-- The no defiers condition is the stated property of the slate-benefit partial-transport model. -/
def NoDefiers {P : POSystem} (S : POSlateSystem P 𝒳 K) : Prop :=
  ∀ᵐ ω ∂P.μ, S.DofZ false ω = true → S.DofZ true ω = true

614e51992153b37f.statement:
/-- The positive aggregate survivors condition is the stated property of the slate-benefit partial-transport model. -/
def PositiveAggregateSurvivors (c : Capacities 𝒳 K) (p : 𝒳 → ℝ) : Prop :=
  0 < c.aggregateMass p

c884f5e4a45b6c88.statement:
/-- The q0 is the object specified here for the slate-benefit partial-transport construction. -/
def q0 (c : Capacities 𝒳 K) (x : 𝒳) : ℝ :=
  ∑ i, c.lower x i -- @realizes q_0(x)(sum of lower capacities)

c0a6f3ef070da86e.statement:
/-- The q1 is the object specified here for the slate-benefit partial-transport construction. -/
def q1 (c : Capacities 𝒳 K) (x : 𝒳) : ℝ :=
  ∑ j, c.upper x j -- @realizes q_1(x)(sum of upper capacities)

32b2d400db0ced17.statement:
/-- The gap is the corresponding numerical quantity in the slate-benefit partial-transport calculation. -/
def gap (c : Capacities 𝒳 K) (x : 𝒳) : ℝ :=
  c.q1 x - c.q0 x -- @realizes \Delta q(x)(q1 minus q0)

983dd1483cb1cafd.statement:
/-- The mass is the corresponding numerical quantity in the slate-benefit partial-transport calculation. -/
def mass (c : Capacities 𝒳 K) (x : 𝒳) : ℝ :=
  min (c.q0 x) (c.q1 x) -- @realizes m(x)(minimum of arm totals)

903caadac1d6c64d.statement:
/-- The aggregate mass is the corresponding numerical quantity in the slate-benefit partial-transport calculation. -/
def aggregateMass (c : Capacities 𝒳 K) (p : 𝒳 → ℝ) : ℝ :=
  ∑ x, p x * c.mass x -- @realizes M(weighted aggregate survivor mass)

350a97bbd4d268f2.statement:
noncomputable def thresholdFlow {P₀ : POSystem.{uV, uVal, uOmega}}
    {Pobs : Measure (ObservedDatum 𝒳 K)} {c : Capacities 𝒳 K}
    (baseline : CompatibleBaseline P₀ Pobs c) (hValid : ValidCapacities c)
    (x : 𝒳) : ThresholdFlowResult P₀ Pobs c where
  lower := thresholdLatentCompletion baseline hValid x (thresholdFlowLower c hValid x)
  upper := thresholdLatentCompletion baseline hValid x (thresholdFlowUpper c hValid x)

bda3b8193f2eff7d.statement:
/-- The uniform aggregate survivor bound condition is the stated property of the slate-benefit partial-transport model. -/
def UniformAggregateSurvivorBound (c : Capacities 𝒳 K) (p : 𝒳 → ℝ) (mstar : ℝ) : Prop :=
  0 < mstar ∧ mstar ≤ c.aggregateMass p -- @realizes m_{\star}(positive uniform aggregate lower bound)

