/-- The direction margin condition is the stated property of the slate-benefit partial-transport model. -/
def DirectionMargin (c : Capacities 𝒳 K) (p : 𝒳 → ℝ) (κσ : ℝ) : Prop :=
  ∀ x, 0 < p x → 0 < c.mass x → κσ ≤ |c.gap x|
